// Iconos de la PWA (Look Makers) incrustados como data URI en base64.
// ICON_192/512 y el icono de Apple usan la imagen de marca (ojo + sello Look Makers),
// pensada como icono de instalacion/home screen. FAVICON usa el sello limpio en fondo
// blanco, mas legible en tamanos muy pequenos (pestana del navegador).

export const ICON_192_DATA_URI =
  "data:image/webp;base64,";

export const ICON_512_DATA_URI =
  "data:image/webp;base64,";

export const APPLE_TOUCH_ICON_DATA_URI =
  "data:image/png;base64,";
